import { expect, expectStatus, test } from "../../fixtures";

test("an insurance certificate with an unreadable expiry date cannot be approved", { tag: "@LIF-08" }, async ({ factory, apiAs }) => {
  // Arrange: a vendor in review whose insurance certificate expiry reads "next spring"
  const { documents, extractions } = await factory.vendorInReview({
    files: { insurance_certificate: "insurance_certificate_unparseable.txt" },
  });
  const insuranceId = extractions.insurance_certificate.id;
  const reviewer = await apiAs("reviewer");

  // Act: the reviewer tries to approve the insurance certificate extraction
  const response = await reviewer.post(`/api/extractions/${insuranceId}/decision`, {
    data: { decision: "approve" },
  });

  // Assert: refused with a 409 and the expiry-missing error code
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("insurance_expiry_missing");

  // Assert: the stored extraction is still awaiting review
  // factory.extraction takes the document ID, not the extraction ID.
  const stored = await factory.extraction(documents.insurance_certificate.id, "reviewer");
  expect(stored.status).toBe("pending_review");
});
